import SwiftUI

/// The web's colours, one per token in docs/brand/tokens.json, named as the token is (`muted-foreground` is
/// `mutedForeground`). Each is the stock colour set in `Colors.xcassets` (an Any slot and a dark slot, both the stock
/// value, and a light slot, the iOS guide's mirror, generated by scripts/gen_tokens.py; Any is the dark value because
/// `UIColor(named:)` returns nil without it) until the person's theme is worn, and then the theme's. They come from
/// `StyleRuntime`, so a body that reads one is drawn again when the look changes; with no theme worn (the extensions, a
/// person with the default look) they are the colour sets and nothing else, and a light or dark trait still selects its own
/// slot, so the app, the Share extension and the widgets follow the system's appearance together.
///
/// They are namespaced because SwiftUI already has `Color.primary` and `Color.secondary`, which mean label colours.
/// Screens use `Palette`, which is built from these; reach for `HVColor` where a token's own name is the point. A colour
/// is never looked up by asset name anywhere else (`Color("...")`), or it would not follow the theme.
enum HVColor {
    private static var worn: PaletteColors { StyleRuntime.shared.colors }

    static var background: Color { worn.background }
    static var foreground: Color { worn.foreground }
    static var card: Color { worn.card }
    static var cardForeground: Color { worn.cardForeground }
    static var muted: Color { worn.muted }
    static var mutedForeground: Color { worn.mutedForeground }
    static var primary: Color { worn.primary }
    static var primaryForeground: Color { worn.primaryForeground }
    static var secondary: Color { worn.secondary }
    static var secondaryForeground: Color { worn.secondaryForeground }
    static var accent: Color { worn.accent }
    static var accentForeground: Color { worn.accentForeground }
    static var border: Color { worn.border }
    static var ring: Color { worn.ring }
    static var destructive: Color { worn.destructive }

    /// The status shades of the Agent keys chips (emerald-400 and amber-400). The web has no token for them; these
    /// are the clamped sRGB values the handoff gives, because Tailwind 4 defines the shades outside sRGB. A worn theme's
    /// `success` and `warning` take their place.
    static var emerald400: Color { worn.success }
    static var amber400: Color { worn.warning }
    /// The memory kind: violet in the dark look, a deeper violet in the light look.
    static var memory: Color { worn.memory }
    /// The flat fill under a label at body size: #2563EB in both stock looks, which is the web's light-look `primary`.
    /// White on it is 5.17:1; white on the dark look's own `primary` is 3.68:1. A worn theme's `action` is the theme's own
    /// button colour, and the label on it is `Palette.onAction`, which is white only in the stock look.
    static var action: Color { worn.action }

    // Fixed colours: drawn outside the tokens, so no look changes them (tokens.json `fixed`). The card brands are in
    // `HVCardBrandTile`.
    static let docPanelBackground = Color(hex: HVTokens.Fixed.docPanelBackground)
    static let docPanelForeground = Color(hex: HVTokens.Fixed.docPanelForeground)
    static let docPanelBorder = Color(hex: HVTokens.Fixed.docPanelBorder, opacity: HVTokens.Fixed.docPanelBorderOpacity)
}
